<script setup>
import {onBeforeUnmount,ref} from 'vue';import {useAccountAccess} from './use-account-access.js';import AccountModal from './AccountModal.vue';import FormField from './FormField.vue';
const emit=defineEmits(['close','saved']);const {session,handleFailure}=useAccountAccess();const original=session.state.identity,version=original.membership.version;const agent=original.membership.kind==='owner'&&['main_agent','sub_agent','sub_branch'].includes(original.account.type);const name=ref(original.user.name),email=ref(original.user.email||''),color=ref(original.account.color||original.brand?.color||'#0D5C63'),currentPassword=ref(''),password=ref(''),confirmation=ref(''),busy=ref(false),error=ref(''),errors=ref({});const controller=new AbortController();
async function save(){if(busy.value)return;busy.value=true;error.value='';errors.value={};try{const fields={};if(email.value.trim()!==(original.user.email||''))fields.email=email.value.trim();if(password.value)Object.assign(fields,{password:password.value,password_confirmation:confirmation.value});if(fields.email||fields.password)fields.current_password=currentPassword.value;if(agent)fields.color=color.value;await session.updateProfile(name.value.trim(),version,controller.signal,fields);emit('saved');}catch(failure){if(failure.name!=='AbortError'){errors.value=failure.errors||{};if(failure.status===409)await session.refresh();error.value=await handleFailure(failure);}}finally{busy.value=false;}}
onBeforeUnmount(()=>controller.abort());
</script>
<template><AccountModal title="تعديل حسابي" section="حسابك" :busy="busy" @close="emit('close')"><p v-if="error" class="notice notice-error" role="alert">{{error}}</p><form @submit.prevent="save"><fieldset class="formgrid" :disabled="busy"><FormField v-model="name" name="own-name" label="اسم الحساب" required :maxlength="120" :error="errors.name"/><FormField v-if="original.account.type!=='pos'" v-model="email" name="own-email" label="البريد الإلكتروني" type="email" :maxlength="190" :error="errors.email"/><FormField v-if="agent" v-model="color" name="own-color" label="لون الوكيل" type="color" :error="errors.color"/><FormField :model-value="original.user.login" name="own-login" label="اسم مستخدم تسجيل الدخول" disabled/><FormField v-model="currentPassword" name="current-password" label="كلمة المرور الحالية" type="password" :error="errors.current_password"/><FormField v-model="password" name="new-password" label="كلمة المرور الجديدة" type="password" :minlength="9" :maxlength="72" :error="errors.password"/><FormField v-model="confirmation" name="confirm-password" label="تأكيد كلمة المرور" type="password" :error="errors.password_confirmation"/></fieldset><footer class="formfoot"><button type="button" class="btn" :disabled="busy" @click="emit('close')">إلغاء</button><button class="btn primary" :disabled="busy">{{busy?'جارٍ الحفظ…':'حفظ البيانات'}}</button></footer></form></AccountModal></template>

